CREATE VIEW [${flyway:defaultSchema}].[vwEventProducts]
AS
SELECT
    e.*,
    ${mjSchema}_isa_p1.[Name],
    ${mjSchema}_isa_p1.[SKU],
    ${mjSchema}_isa_p1.[ProductTypeID],
    ${mjSchema}_isa_p1.[ProductCategoryID],
